mapper.select:
SELECT distinct cam.*,camd.model_id,cac.name channelName, cap.name providerName FROM cat_ai_model cam LEFT JOIN cat_ai_model_default camd on cam.id = camd.model_id LEFT JOIN cat_ai_channel cac on cam.channel_id = cac.id LEFT JOIN cat_ai_provider cap on cac.provider_id = cap.id
and cam.type = #{param.type}
ORDER BY camd.model_id desc, cac.name, cap.name, cam.name

SELECT count(1) FROM cat_ai_model_default camd
INNER JOIN cat_ai_model cam on camd.model_id = cam.id

    cam.id = #{modelId}

SELECT distinct cam.*,camd.model_id FROM cat_ai_model cam LEFT JOIN cat_ai_model_default camd on cam.id = camd.model_id
and cam.channel_id = #{channelId}
ORDER BY camd.model_id desc
